CREATE TABLE "accounts_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(20) NOT NULL, "uid" varchar(191) NOT NULL, "email" varchar(254) NOT NULL, "login" varchar(150) NOT NULL, "created_at" datetime NOT NULL, "last_login_at" datetime NULL, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_social_provider_uid" UNIQUE ("provider", "uid"), CONSTRAINT "uniq_social_user_provider" UNIQUE ("user_id", "provider"));
CREATE INDEX "accounts_socialaccount_user_id_4a644128" ON "accounts_socialaccount" ("user_id");
